#!/usr/bin/env python3
"""
INVENIO — Script de configuration automatique
Lancez depuis la RACINE du projet GitHub :
    python setup_invenio.py

Ce script :
  1. Crée tous les répertoires manquants
  2. Écrit tous les fichiers frontend et deploy
  3. Copie les PNG dans ui/public/covers/
  4. Applique le correctif dans Projet.tsx
  5. Vérifie le résultat
"""
import base64, shutil, sys, os
from pathlib import Path

ROOT = Path(__file__).parent.resolve()
OK = []; FAIL = []

def w(rel, b64):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    OK.append(rel)
    print(f"  ✓  {rel}")

print("\n" + "═"*60)
print("  INVENIO — Installation automatique")
print("═"*60)

# ── Étape 1 : Fichiers frontend & deploy ─────────────────────────
print("\n[1/4] Écriture des fichiers...")
w('ui/src/lib/machines.ts', '')
w('ui/src/lib/theme.tsx', '')
w('ui/src/lib/sessionContext.ts', '')
w('ui/src/components/ui/atoms.tsx', '')
w('ui/src/components/layout/AnimatedBackground.tsx', '')
w('ui/src/components/layout/Navigation.tsx', '')
w('ui/src/App.tsx', '')
w('ui/src/pages/Home.tsx', '')
w('ui/src/pages/Machine.tsx', '')
w('ui/src/pages/Projet.tsx', '')
w('ui/src/pages/Contacts.tsx', '')
w('ui/src/pages/Options.tsx', '')
w('ui/src/pages/Generate.tsx', '')
w('ui/src/api/client.ts', '')
w('deploy/docker-compose.yml', '')
w('deploy/Caddyfile', '')
w('deploy/.env.example', '')
w('deploy/postgres-init/01-init.sql', '')
w('deploy/install.sh', '')
w('deploy/scripts/tunnel.sh', '')
w('deploy/scripts/update.sh', '')
w('deploy/scripts/migrate_baserow_to_nocodb.py', '')
w('src/services/nocodb_client.py', '')
w('src/api/_static.py', '')
w('Dockerfile', '')

# ── Étape 2 : Correctif Projet.tsx ─────────────────────────────
print("\n[2/4] Application du correctif Projet.tsx...")
p = ROOT / "ui/src/pages/Projet.tsx"
if p.exists():
    txt = p.read_text(encoding="utf-8")
    old = "setSuggestions(results.results ?? [])"
    new = "setSuggestions(results)"
    if old in txt:
        p.write_text(txt.replace(old, new), encoding="utf-8")
        print("  ✓  Correctif appliqué")
    else:
        print("  ✓  Déjà correct")

# ── Étape 3 : PNG → ui/public/covers/ ──────────────────────────
print("\n[3/4] Copie des PNG vers ui/public/covers/...")
covers = ROOT / "ui/public/covers"
covers.mkdir(parents=True, exist_ok=True)
pngs = list(ROOT.glob("*.png"))
if not pngs:
    print("  ⚠  Aucun PNG trouvé à la racine — vérifiez que les fichiers sont bien là")
else:
    for png in pngs:
        shutil.copy2(png, covers / png.name)
    print(f"  ✓  {len(pngs)} PNG copiés")

# ── Étape 4 : Permissions scripts shell ──────────────────────────
print("\n[4/4] Permissions scripts shell...")
for sh in ["deploy/install.sh","deploy/scripts/tunnel.sh","deploy/scripts/update.sh"]:
    sp = ROOT / sh
    if sp.exists():
        sp.chmod(0o755)
print("  ✓  Permissions ok")

# ── Résumé ─────────────────────────────────────────────────────
print("\n" + "═"*60)
print(f"  ✓  {len(OK)} fichiers installés")
print("═"*60)
print("""
Prochaine étape — tester en local :
  cd ui && npm install && npm run dev
Puis ouvrez : http://localhost:5173
""")